    {
      "category": "wrong_value",
      "components": ["C12"],
      "pins": ["C12.1", "C12.2"],
      "nets": ["BAT+", "GND"],
      "observed": "C12 is specified in the netlist as 2.2mF, i.e. millifarads, and the SPICE deck models it as 2.2m on the BAT+ input-capacitor net.",
      "expected": "The design specification requires C12 to be 2.2 µF, matching the FAN53610 recommended input capacitor value.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(value \"2.2mF\")"
        },
        {
          "source": "spec",
          "quote": "`C12` (2.2 µF) on `BAT+`→GND is the input cap"
        },
        {
          "source": "spice",
          "quote": "C12 BAT+ 0 2.2m"
        }
      ],
      "impact": "The input capacitance is 1000× larger than intended and is physically inconsistent with the 0805 footprint. This can cause excessive inrush current, regulator startup problems, or indicates a sourcing/assembly mistake.",
      "confidence": 0.95
    },
    {
      "category": "wrong_value",
      "components": ["C1"],
      "pins": ["C1.1", "C1.2"],
      "nets": ["GND", "Display_Power_Switch"],
      "observed": "C1 is populated as 0.1uF/16V between GND and the Display_Power_Switch net.",
      "expected": "The specification lists C1 as 1uF/25V for the EPD power-rail decoupling network.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(value \"0.1uF/16V\")"
        },
        {
          "source": "spec",
          "quote": "C1/C5/C7/C8/C9/C10 = 1 µF/25 V"
        },
        {
          "source": "spice",
          "quote": "C1 0 Display_Power_Switch 0.1uF"
        }
      ],
      "impact": "The EPD power switch rail has a smaller and lower-voltage-rated decoupling capacitor than specified, which can increase supply noise and transient susceptibility on the display power path.",
      "confidence": 0.6
    }
  ],
  "summary": "The build contains component-value deviations from the intended design; the clearest is C12 being 2.2mF instead of the specified 2.2µF input capacitor, with C1 also differing from the specified EPD-rail capacitor value."
}

